select project.* , enter.business_name as crmEnterpriseWarehousingName, a.name as structureTypeConfigurationName, project.estimated_cost as estimatedCost, b.name as projectLevelConfigName, dept.name as departmentName, user_a.name as createUserName, user_b.name as informationOperatorUserName from crm_project_information_warehousing as project left join crm_enterprise_warehousing as enter on enter.id = project.crm_enterprise_warehousing_id and enter.bool_delete_enum = 0 left join crm_project_information_config as a on project.structure_type_configuration_id = a.id and a.bool_delete_enum = 0 left join crm_project_information_config as b on project.project_level_config_id = b.id and b.bool_delete_enum = 0 left join sys_department as dept on dept.id = project.department_id and dept.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = project.create_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = project.information_operator_user_id and user_a.bool_delete_enum = 0
project.bool_delete_enum = 0 and project.crm_check_status_enum = 2 and project.crm_project_schedule_type_enum != 11 and project.crm_project_schedule_type_enum != 7
AND DATE(project.informant_date_time)>=DATE(#{startDate})
AND DATE(project.informant_date_time)<=DATE(#{endDate})
and enter.country_id = #{countryId}
and enter.province_id = #{provinceId}
and enter.city_id = #{cityId}
and enter.region_id = #{regionId}
and project.structure_type_configuration_id = #{structureTypeConfigurationId}
and project.department_id IN
#{deptId}
and project.project_name like concat('%',#{projectName},'%')
and enter.business_name like concat('%',#{crmEnterpriseWarehousingName},'%')
and user_a.name like concat('%',#{informantUserName},'%')
and (project.information_operator_dept_id IN
#{deptId}
or project.information_operator_user_id = #{userId})
and project.information_operator_dept_id IN
#{deptId}
-- 只查看自己的内容 and project.information_operator_user_id = #{userId}
order by project.informant_date_time desc

select supplier.id as id, supplier.create_time as informantDateTime, supplier.ca_lock_date as caLockDate, supplier.deadline_for_acceptance_time as deadlineForAcceptanceTime, enter.business_name as businessName, enter.credit_code as creditCode, supplier.country_name as countryName, supplier.province_name as provinceName, supplier.city_name as cityName, supplier.region_name as regionName, basice_config1.name as unitPropertyAllocationConfigName, basice_config2.name as unitClassConfigurationName, basice_config3.name as industryConfigurationName, basice_config4.name as unitReputationAllocationConfigName, user_a.name as informantUserName, user_b.name as createUserName, supplier.attachment_ids as attachmentIdsByString, enter.business_phone as businessPhone, enter.business_email as businessEmail, warehousing.project_name as projectName from crm_supplier_warehousing as supplier left join crm_project_information_warehousing as warehousing on warehousing.id = supplier.crm_project_information_warehousing_id and warehousing.bool_delete_enum = 0 left join crm_enterprise_warehousing as enter on enter.id = supplier.crm_enterprise_warehousing_id and enter.bool_delete_enum = 0 left join crm_basics_config as basice_config1 on basice_config1.id = enter.unit_property_allocation_config_id and basice_config1.bool_delete_enum = 0 left join crm_basics_config as basice_config2 on basice_config2.id = enter.unit_class_configuration_id and basice_config2.bool_delete_enum = 0 left join crm_basics_config as basice_config3 on basice_config3.id = enter.industry_configuration_id and basice_config3.bool_delete_enum = 0 left join crm_basics_config as basice_config4 on basice_config4.id = enter.unit_reputation_allocation_config_id and basice_config4.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = supplier.informant_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = supplier.create_user_id and user_b.bool_delete_enum = 0
supplier.bool_delete_enum =0
and supplier.crm_check_status_enum = #{crmCheckStatusEnum}
and supplier.crm_record_type_enum = #{checkRecord}
and date(supplier.create_time) >= date(#{startDate})
and date(supplier.create_time) <= date(#{endDate})
and supplier.countr_id = #{countryId}
and supplier.province_id = #{provinceId}
and supplier.city_id = #{cityId}
and supplier.region_id = #{regionId}
and enter.unit_property_allocation_config_id = #{unitPropertyAllocationConfigId}
and enter.unit_class_configuration_id = #{unitClassConfigurationId}
and enter.industry_configuration_id = #{industryConfigurationId}
and enter.unit_reputation_allocation_config_id = #{unitReputationAllocationConfigId}
and enter.business_name like concat('%',#{businessName},'%')
and enter.credit_code like concat('%',#{creditCode},'%')
and user_a.name like concat('%',#{informantUserName},'%')
order by supplier.create_time desc

select gover.*,
gover.create_time as informantDateTime,
gover.informant_date_time as informantDateTime,
enter.business_name as businessName, enter.address as address, project_warehousing.id as crmProjectInformationWarehousingId, project_warehousing.project_name as crmProjectInformationWarehousingName, basice_config1.name as unitPropertyAllocationConfigName, basice_config2.name as unitClassConfigurationName, basice_config3.name as industryConfigurationName, basice_config4.name as unitReputationAllocationConfigName, user_a.name as informantUserName, user_b.name as createUserName from crm_government_warehousing as gover left join crm_enterprise_warehousing as enter on enter.id = gover.crm_enterprise_warehousing_id and enter.bool_delete_enum = 0 left join crm_basics_config as basice_config1 on basice_config1.id = enter.unit_property_allocation_config_id and basice_config1.bool_delete_enum = 0 left join crm_basics_config as basice_config2 on basice_config2.id = enter.unit_class_configuration_id and basice_config2.bool_delete_enum = 0 left join crm_basics_config as basice_config3 on basice_config3.id = enter.industry_configuration_id and basice_config3.bool_delete_enum = 0 left join crm_basics_config as basice_config4 on basice_config4.id = enter.unit_reputation_allocation_config_id and basice_config4.bool_delete_enum = 0 left join sys_user as user_a on user_a.id = enter.informant_user_id and user_a.bool_delete_enum = 0 left join sys_user as user_b on user_b.id = enter.create_user_id and user_b.bool_delete_enum = 0 left join crm_project_information_warehousing as project_warehousing on project_warehousing.id = gover.crm_project_information_warehousing_id and project_warehousing.bool_delete_enum = 0
gover.bool_delete_enum = 0
and gover.crm_record_type_enum = #{checkRecord}
and gover.crm_check_status_enum = #{crmCheckStatusEnum}
and gover.create_time >= #{startDate}
and gover.create_time <= #{endDate}
and gover.informant_date_time >= #{startDate}
and gover.informant_date_time <= #{endDate}
and enter.country_id = #{countryId}
and enter.province_id = #{provinceId}
and enter.city_id = #{cityId}
and enter.region_id = #{regionId}
and enter.unit_property_allocation_config_id = #{unitPropertyAllocationConfigId}
and enter.unit_class_configuration_id = #{unitClassConfigurationId}
and enter.industry_configuration_id = #{industryConfigurationId}
and enter.unit_reputation_allocation_config_id = #{unitReputationAllocationConfigId}
and enter.business_name like concat('%',#{businessName},'%')
and enter.credit_code like concat('%',#{creditCode},'%')
and user_a.name like concat('%',#{informantUserName},'%')
order by gover.create_time desc
order by gover.informant_date_time desc
